	ChangeTenantSubscription(context.Context, *ChangeTenantSubscriptionReq) (*TenantBillingResp, error)
	// 立即或周期末取消订阅。
	CancelTenantSubscription(context.Context, *CancelTenantSubscriptionReq) (*TenantBillingResp, error)
